    min_count[0] = 0
    best_prev = [None] * (target + 1)

    for denomination, max_count in coins:
        if denomination <= 0 or max_count <= 0:
            continue

        for start in range(denomination):
            window = []
            for i in range(start, target + 1, denomination):
                if min_count[i] < POS_INF:
                    window.append((min_count[i] - (i // denomination), i))
                else:
                    window.append((POS_INF, i))

                left = i - max_count * denomination
                if left >= 0:
                    if window[0][1] == left:
                        window.pop(0)

                if window and window[0][0] < POS_INF:
                    new_count = window[0][0] + (i // denomination)
                    if new_count < min_count[i]:
                        min_count[i] = new_count
                        best_prev[i] = left

    if min_count[target] == POS_INF:
        return None

    multiset = []
    cur = target
    while cur > 0:
        prev = best_prev[cur]
        multiset.append(cur - prev)
        cur = prev

    multiset.sort()
    return multiset
