    def get_sum(i, j):
        return prefix_sum[j + 1] - prefix_sum[i]

    memo = {}

    def dp(i, j):
        if j - i + 1 < k:
            return 0
        if j - i + 1 == k:
            return get_sum(i, j)
        if (i, j) in memo:
            return memo[(i, j)]

        min_cost = float('inf')
        # Try all possible ways to split the range [i, j] into valid segments
        # We need to merge k consecutive piles, so we can only merge when the remaining
        # piles can be grouped into valid merges
        for mid in range(i, j, k - 1):
            if mid + 1 <= j:
                cost = dp(i, mid) + dp(mid + 1, j)
                if cost < min_cost:
                    min_cost = cost

        # Add the cost of merging the final k piles
        # But we need to ensure that the total number of piles can be reduced to 1
        # The key insight: we can only merge when the number of piles is reduced by (k-1) each time
        # So we need to check if the current segment can be merged into one pile
        if (j - i + 1 - 1) % (k - 1) == 0:
            min_cost += get_sum(i, j)

        memo[(i, j)] = min_cost
        return min_cost

