def kth_smallest_pair_sum(a: list[int], b: list[int], k: int) -> int:
    if not a or not b:
        return 0
    m, n = len(a), len(b)
    # Use binary search on the value range
    lo, hi = a[0] + b[0], a[-1] + b[-1]
    while lo < hi:
        mid = (lo + hi) // 2
        # Count how many sums <= mid
        count = 0
        j = n - 1
        for i in range(m):
            while j >= 0 and a[i] + b[j] > mid:
                j -= 1
            count += (j + 1)
        if count >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
